// Leemos el template HTML hardcodeado
let template = `<!DOCTYPE html>
<html lang="es">
<head>
    <meta charset="UTF-8">
    <title>CV - {{nombre_completo}} | {{titulo_adaptado}}</title>
    <style>
        @import url('https://fonts.googleapis.com/css2?family=Montserrat:ital,wght@0,400;0,600;0,700;1,400&display=swap');
        @page { size: A4; margin: 1.5cm; }
        * { box-sizing: border-box; margin: 0; padding: 0; }
        body { font-family: 'Montserrat', sans-serif; font-size: 10.5pt; line-height: 1.4; color: #111; background-color: #fff; }
        h1 { font-size: 20pt; text-align: center; font-weight: 700; margin-bottom: 5px; text-transform: uppercase; letter-spacing: 1px; }
        .contact-info { text-align: center; font-size: 9.5pt; margin-bottom: 15px; color: #444; }
        .contact-info a { color: #0056b3; text-decoration: none; }
        h2 { font-size: 12pt; font-weight: 700; text-transform: uppercase; border-bottom: 1px solid #000; margin-top: 12px; margin-bottom: 8px; padding-bottom: 2px; color: #222; }
        .experience-item { margin-bottom: 12px; }
        .experience-header, .experience-subheader { display: flex; justify-content: space-between; align-items: baseline; }
        .experience-header { font-weight: 700; }
        .experience-subheader { font-style: italic; margin-bottom: 3px; font-weight: 600; color: #444; }
        ul { list-style-type: disc; padding-left: 18px; }
        li { margin-bottom: 3px; }
        .education-item { margin-bottom: 8px; }
        .education-header { display: flex; justify-content: space-between; align-items: baseline; font-weight: 700; }
        .education-subheader { font-style: italic; font-size: 9.5pt; color: #555; }
        .skills-section p { margin-bottom: 3px; line-height: 1.5; }
    </style>
</head>
<body>
    <h1>{{nombre_completo}}</h1>
    <div class="contact-info">
        {{ciudad}} | <a href="mailto:{{email}}">{{email}}</a> | <a href="{{linkedin_url}}">LinkedIn</a> | <a href="{{github_url}}">GitHub</a>
    </div>
    <h2>{{seccion_perfil}}</h2>
    <p>{{resumen_perfil}}</p>
    <h2>{{seccion_experiencia}}</h2>
    {{experiencias_html}}
    <h2>{{seccion_educacion}}</h2>
    {{educacion_html}}
    <h2>{{seccion_habilidades}}</h2>
    <div class="skills-section">
        <p>{{skills_html}}</p>
    </div>
</body>
</html>`;

// Parsear respuesta de la IA
const rawAiResponse = $input.item.json.candidates[0].content.parts[0].text;
const cvData = JSON.parse(rawAiResponse);

// Datos personales desde el primer nodo (Webhook body) o fallback hardcodeado
const persona = {
  nombre_completo: 'Ezequiel Enrico Areco',
  ciudad: 'Buenos Aires, Argentina',
  email: 'EzequielEnrico15@gmail.com',
  telefono: '+54 11 1234-5678',
  linkedin_url: 'https://www.linkedin.com/in/ezequiel-enrico/',
  github_url: 'https://github.com/arecofix'
};

// Reemplazar placeholders dinámicos (contenido de la IA y traducciones)
template = template.replace('{{titulo_adaptado}}', cvData.titulo_adaptado || '');
template = template.replace('{{resumen_perfil}}', cvData.resumen_perfil || '');
template = template.replace('{{experiencias_html}}', cvData.experiencias_html || '');
template = template.replace('{{educacion_html}}', cvData.educacion_html || '');
template = template.replace('{{skills_html}}', cvData.skills_html || '');
template = template.replace('{{seccion_perfil}}', cvData.seccion_perfil || 'Perfil Profesional');
template = template.replace('{{seccion_experiencia}}', cvData.seccion_experiencia || 'Experiencia Profesional');
template = template.replace('{{seccion_educacion}}', cvData.seccion_educacion || 'Educación y Certificaciones');
template = template.replace('{{seccion_habilidades}}', cvData.seccion_habilidades || 'Habilidades Técnicas');

// Reemplazar los datos personales
template = template.replace(/{{nombre_completo}}/g, persona.nombre_completo);
template = template.replace(/{{ciudad}}/g, persona.ciudad);
template = template.replace(/{{email}}/g, persona.email);
template = template.replace(/{{telefono}}/g, persona.telefono);
template = template.replace(/{{linkedin_url}}/g, persona.linkedin_url);
template = template.replace(/{{github_url}}/g, persona.github_url);

const buffer = Buffer.from(template, 'utf-8');
const tituloSlug = (cvData.titulo_adaptado || 'CV').replace(/\s+/g, '_').replace(/[^a-zA-Z0-9_]/g, '');

return {
  json: {
    html_final: template,
    file_name: `CV_Ezequiel_${tituloSlug}.pdf`
  },
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType: 'text/html',
      fileName: 'index.html'
    }
  }
};

const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const fileName = $('Ensamblaje HTML').item.json.file_name || 'CV_Ezequiel.pdf';

return {
  json: {
    url_pdf: `data:application/pdf;base64,${buffer.toString('base64')}`,
    file_name: fileName
  }
};
